using System.Text;

namespace Wlrix.PaletteGen;

public static class Emit
{
    private const string DoNotEdit =
        "GENERATED by wlrix-assets/tools/palettegen. Do not edit; edit the\n" +
        "    palette JSON in wlrix-assets/palette/ and re-run `just palette`.";

    /// <summary>
    /// Avalonia resource key -> palette role. Explicit rather than derived from
    /// the role name: several keys are load-bearing names the control templates
    /// already reference, and two roles deliberately share one color.
    /// </summary>
    private static readonly (string Key, string Role)[] SchemeKeys =
    [
        // Surfaces
        ("WlrixFace",                 "face"),
        ("WlrixPanel",                "panel"),
        ("WlrixReadOnly",             "readOnly"),
        ("WlrixListBackground",       "listBackground"),
        ("WlrixTextBackground",       "textFieldBackground"),
        ("WlrixTextAreaBackground",   "textBackground"),
        ("WlrixViewBackground",       "viewBackground"),
        ("WlrixMenubarBackground",    "menubarBackground"),
        ("WlrixTooltipBackground",    "tooltipBackground"),
        ("WlrixIndicatorBackground",  "indicatorBackground"),

        // Armed / pressed face
        ("WlrixSelect",               "armed"),

        // Text
        ("WlrixForeground",           "foreground"),
        ("WlrixTextForeground",       "foreground"),
        ("WlrixViewForeground",       "foreground"),
        ("WlrixTooltipForeground",    "tooltipForeground"),
        ("WlrixDisabledForeground",   "disabledForeground"),
        ("WlrixSelection",            "selectionBackground"),
        ("WlrixSelectionForeground",  "selectionForeground"),

        // Bevels. WlrixTopShadow/WlrixBottomShadow are the button-face pair,
        // which is what the bulk of the templates bevel against.
        ("WlrixTopShadow",            "faceTopShadow"),
        ("WlrixBottomShadow",         "faceBottomShadow"),
        ("WlrixPanelTopShadow",       "panelTopShadow"),
        ("WlrixPanelBottomShadow",    "panelBottomShadow"),
        ("WlrixTroughTopShadow",      "troughTopShadow"),
        ("WlrixTroughBottomShadow",   "troughBottomShadow"),
        ("WlrixTextTopShadow",        "textTopShadow"),
        ("WlrixTextBottomShadow",     "textBottomShadow"),
        ("WlrixOuterLine",            "outerLine"),

        // Pixmap buttons invert the bevel on purpose.
        ("WlrixPixmapButtonFill",         "pixmapButtonFill"),
        ("WlrixPixmapButtonTopShadow",    "pixmapButtonTopShadow"),
        ("WlrixPixmapButtonBottomShadow", "pixmapButtonBottomShadow"),

        // Scrollbars / sliders
        ("WlrixTrough",               "trough"),
        ("WlrixScrollBarControl",     "scrollBarControl"),

        // Indicators
        ("WlrixAccent",               "accent"),
        ("WlrixCheck",                "checkColor"),
        ("WlrixRadio",                "radioColor"),
        ("WlrixLightRadioFill",       "lightRadioFill"),
        ("WlrixDisabledCheck",        "disabledCheck"),
        ("WlrixSelectFill",           "selectFill"),
        ("WlrixIndicatorLight",       "indicatorLight"),

        // Status / links
        ("WlrixError",                "error"),
        ("WlrixWarning",              "warning"),
        ("WlrixInformation",          "information"),
        ("WlrixLink",                 "link"),
        ("WlrixLinkVisited",          "linkVisited"),
        ("WlrixLinkActive",           "linkActive"),

        // Alternate panel backgrounds (Base/SaSpec convention)
        ("WlrixReadOnlyPanel",        "readOnlyPanel"),
        ("WlrixReadWritePanel",       "readWritePanel"),
    ];

    private static Rgb Get(Palette p, string role) =>
        p.Resolved.TryGetValue(role, out var c)
            ? c
            : throw new InvalidDataException($"palette '{p.Id}' has no role '{role}'");

    public static string Scheme(Palette p, string schemeName)
    {
        var sb = new StringBuilder();
        sb.AppendLine("<!--");
        sb.AppendLine($"    {DoNotEdit}");
        sb.AppendLine();
        sb.AppendLine($"    {p.Name}");
        sb.AppendLine($"    Source: {p.Source}");
        sb.AppendLine("-->");
        sb.AppendLine("<ResourceDictionary xmlns=\"https://github.com/avaloniaui\"");
        sb.AppendLine("                    xmlns:x=\"http://schemas.microsoft.com/winfx/2006/xaml\"");
        sb.AppendLine("                    xmlns:sys=\"clr-namespace:System;assembly=System.Runtime\">");
        sb.AppendLine();
        sb.AppendLine("    <!-- Which scheme this is, so WlrixTheme can find the one merged dictionary it");
        sb.AppendLine("         owns and replace it. It cannot look for a ResourceInclude: the XAML compiler");
        sb.AppendLine("         resolves those away at build time, leaving a plain ResourceDictionary with");
        sb.AppendLine("         nothing to tell it apart from a control theme. -->");
        sb.AppendLine($"    <sys:String x:Key=\"{SchemeIdKey}\">{p.Id}</sys:String>");
        sb.AppendLine();

        foreach (var (key, role) in SchemeKeys)
            sb.AppendLine($"    <Color x:Key=\"{key}Color\">{Get(p, role).Hex}</Color>");

        sb.AppendLine("</ResourceDictionary>");
        return sb.ToString();
    }

    /// <summary>
    /// The resource key every scheme dictionary carries, holding its own id.
    ///
    /// Emitted into the dictionaries and into the catalog from the same constant, so the name
    /// the theme looks for and the name the schemes answer to cannot drift apart.
    /// </summary>
    private const string SchemeIdKey = "WlrixSchemeId";

    /// <summary>
    /// The brush layer is the same for every scheme (each brush just points at
    /// its Color key), so it is emitted once instead of being copied into all
    /// of them.
    /// </summary>
    public static string Brushes(Palette p)
    {
        var sb = new StringBuilder();
        sb.AppendLine("<!--");
        sb.AppendLine($"    {DoNotEdit}");
        sb.AppendLine();
        sb.AppendLine("    One SolidColorBrush per Color key. Scheme-independent: swapping the");
        sb.AppendLine("    merged scheme dictionary repoints every brush through DynamicResource.");
        sb.AppendLine("-->");
        sb.AppendLine("<ResourceDictionary xmlns=\"https://github.com/avaloniaui\"");
        sb.AppendLine("                    xmlns:x=\"http://schemas.microsoft.com/winfx/2006/xaml\">");

        foreach (var (key, _) in SchemeKeys)
            sb.AppendLine($"    <SolidColorBrush x:Key=\"{key}\" Color=\"{{DynamicResource {key}Color}}\" />");

        sb.AppendLine("</ResourceDictionary>");
        return sb.ToString();
    }

    /// <summary>
    /// The scheme catalog for the C# side: <c>Wlrix.Avalonia/Schemes/SchemeCatalog.g.cs</c>.
    ///
    /// The Rust consumers get this for free — <c>wlrix_ui::palette::ALL</c> carries every
    /// scheme's id, name, gamma and dark flag, because a <c>Palette</c> is a value there. The
    /// C# side had nothing equivalent: the theme shipped four scheme dictionaries and no way to
    /// find out that they existed, so the demo hardcoded their names and a settings panel would
    /// have had to hardcode them again. This is the same list, emitted from the same run over
    /// the same JSON, so a new palette file becomes a new entry in every scheme picker without
    /// anyone editing one.
    /// </summary>
    public static string SchemeCatalog(IReadOnlyList<Palette> palettes, Palette standard,
                                       Func<string, string> schemeName)
    {
        var sb = new StringBuilder();
        sb.AppendLine("// SPDX-License-Identifier: MIT");
        sb.AppendLine("//");
        sb.AppendLine($"// {DoNotEdit.Replace("\n    ", "\n// ")}");
        sb.AppendLine("//");
        sb.AppendLine("// One entry per scheme JSON, so a scheme picker in an app lists exactly what the");
        sb.AppendLine("// compositor can be set to. Ordered by name rather than by filename, which is what a");
        sb.AppendLine("// picker wants: the three gamma bakes read 1.0, 1.7, 2.4 instead of 1.0, 2.4, 1.7.");
        sb.AppendLine();
        // Required, not tidiness: a `.g.cs` name puts the file in the "generated code" nullable
        // context, where an annotation without an explicit directive is a hard error (CS8669).
        sb.AppendLine("#nullable enable");
        sb.AppendLine();
        sb.AppendLine("using System.Collections.Generic;");
        sb.AppendLine("using System.Linq;");
        sb.AppendLine();
        sb.AppendLine("namespace Wlrix.Avalonia;");
        sb.AppendLine();
        sb.AppendLine("/// <summary>One color scheme: what to call it, and where its dictionary lives.</summary>");
        sb.AppendLine("/// <param name=\"Id\">What a wlRIX config file names, and what the settings daemon writes.</param>");
        sb.AppendLine("/// <param name=\"Name\">Human-readable, for a list in a settings panel.</param>");
        sb.AppendLine("/// <param name=\"Gamma\">The display gamma this bake was made for.</param>");
        sb.AppendLine("/// <param name=\"IsDark\">The scheme's own IsDarkScheme, for an app that has to pick a contrast.</param>");
        sb.AppendLine("/// <param name=\"ResourceUri\">The <c>avares://</c> URI of its ResourceDictionary.</param>");
        sb.AppendLine("public sealed record WlrixScheme(");
        sb.AppendLine("    string Id,");
        sb.AppendLine("    string Name,");
        sb.AppendLine("    string Gamma,");
        sb.AppendLine("    bool IsDark,");
        sb.AppendLine("    string ResourceUri);");
        sb.AppendLine();
        sb.AppendLine("/// <summary>Every color scheme this build of the theme ships.</summary>");
        sb.AppendLine("public static class WlrixSchemes");
        sb.AppendLine("{");
        sb.AppendLine("    /// <summary>");
        sb.AppendLine("    /// The resource key every scheme dictionary carries, holding its own id.");
        sb.AppendLine("    /// </summary>");
        sb.AppendLine("    /// <remarks>");
        sb.AppendLine("    /// How <c>WlrixTheme</c> finds the one merged dictionary it owns. It cannot look for");
        sb.AppendLine("    /// a <c>ResourceInclude</c>: the XAML compiler resolves those away at build time,");
        sb.AppendLine("    /// leaving a plain <c>ResourceDictionary</c> indistinguishable from a control theme.");
        sb.AppendLine("    /// </remarks>");
        sb.AppendLine($"    public const string IdKey = \"{SchemeIdKey}\";");
        sb.AppendLine();
        sb.AppendLine("    /// <summary>Every scheme, ordered by name.</summary>");
        sb.AppendLine("    public static IReadOnlyList<WlrixScheme> All { get; } =");
        sb.AppendLine("    [");
        foreach (var p in palettes.OrderBy(p => p.Name, StringComparer.Ordinal))
        {
            var uri = $"avares://Wlrix.Avalonia/Schemes/{schemeName(p.Id)}.axaml";
            sb.AppendLine($"        new(\"{p.Id}\", \"{p.Name}\", \"{p.Gamma}\", " +
                          $"{(p.Dark ? "true" : "false")}, \"{uri}\"),");
        }
        sb.AppendLine("    ];");
        sb.AppendLine();
        sb.AppendLine("    /// <summary>");
        sb.AppendLine("    /// What an app renders in when nothing has said otherwise, and what an id naming no");
        sb.AppendLine("    /// shipped scheme falls back to. The same default the Rust side takes.");
        sb.AppendLine("    /// </summary>");
        sb.AppendLine($"    public static WlrixScheme Default {{ get; }} = ById(\"{standard.Id}\")!;");
        sb.AppendLine();
        sb.AppendLine("    /// <summary>");
        sb.AppendLine("    /// The scheme an id names, or <c>null</c> if it names none.");
        sb.AppendLine("    /// </summary>");
        sb.AppendLine("    /// <remarks>");
        sb.AppendLine("    /// Null rather than a fallback, as <c>wlrix_ui::palette::by_id</c> does: only the");
        sb.AppendLine("    /// caller knows whether an unrecognized id deserves a warning and the default, or is");
        sb.AppendLine("    /// a mistake worth reporting.");
        sb.AppendLine("    /// </remarks>");
        sb.AppendLine("    public static WlrixScheme? ById(string? id) =>");
        sb.AppendLine("        All.FirstOrDefault(scheme => scheme.Id == id);");
        sb.AppendLine("}");
        return Trimmed(sb);
    }

    /// <summary>
    /// The Rust side, as one file: <c>wlrix-ui/src/palette/generated.rs</c>.
    ///
    /// This replaced three hand-kept subsets -- 13 constants for the compositor in smithay's
    /// <c>Color32F</c>, 23 for the greeter and 12 for the desktop in a packed <c>u32</c> --
    /// which between them had three names for one color and left the window chrome bound to
    /// none of them. One struct, every role, one color type, and the palette is a value a
    /// running program can swap rather than a constant baked into the call site.
    /// </summary>
    public static string RustUi(IReadOnlyList<Palette> palettes, Palette standard)
    {
        var sb = new StringBuilder();
        sb.AppendLine("// SPDX-License-Identifier: GPL-3.0-or-later");
        sb.AppendLine("//");
        sb.AppendLine($"// {DoNotEdit.Replace("\n    ", "\n// ")}");
        sb.AppendLine("//");
        sb.AppendLine("// One `Palette` per scheme and gamma bake. The struct, the role table and");
        sb.AppendLine("// every static below come from one generator run over the same JSON, so a");
        sb.AppendLine("// renamed role cannot leave the accessors behind.");
        sb.AppendLine();
        sb.AppendLine("// A palette is emitted whole; consumers land over time, so not every role");
        sb.AppendLine("// has a caller yet.");
        sb.AppendLine("#![allow(dead_code)]");
        sb.AppendLine();
        sb.AppendLine("use crate::color::Rgb;");
        sb.AppendLine();

        var roles = standard.Resolved.Keys.ToArray();
        var metrics = standard.Metrics.Keys.ToArray();

        // --- Metrics -----------------------------------------------------------------
        sb.AppendLine("/// Motif geometry, in logical pixels.");
        sb.AppendLine("///");
        sb.AppendLine("/// Travels with the colors because a bevel needs both: the shadow pair is what");
        sb.AppendLine("/// it is drawn in and the thickness is how much of it there is.");
        sb.AppendLine("#[derive(Debug, Clone, Copy, PartialEq, Eq)]");
        sb.AppendLine("pub struct Metrics {");
        foreach (var key in metrics)
        {
            sb.AppendLine($"    /// `{key}`");
            sb.AppendLine($"    pub {Snake(key)}: i32,");
        }
        sb.AppendLine("}");
        sb.AppendLine();

        // --- Palette -----------------------------------------------------------------
        sb.AppendLine("/// One resolved color scheme.");
        sb.AppendLine("///");
        sb.AppendLine("/// `Copy` and `'static`, so it is passed as `&'static Palette` and nothing that");
        sb.AppendLine("/// holds one grows a lifetime parameter.");
        sb.AppendLine("#[derive(Debug, Clone, Copy, PartialEq, Eq)]");
        sb.AppendLine("pub struct Palette {");
        sb.AppendLine("    /// The id `by_id` answers to, and what a config file names.");
        sb.AppendLine("    pub id: &'static str,");
        sb.AppendLine("    /// Human-readable, for a settings panel to list.");
        sb.AppendLine("    pub name: &'static str,");
        sb.AppendLine("    pub gamma: &'static str,");
        sb.AppendLine("    /// The scheme's own `IsDarkScheme`.");
        sb.AppendLine("    pub dark: bool,");
        sb.AppendLine("    pub metrics: Metrics,");
        foreach (var role in roles)
        {
            sb.AppendLine($"    /// `{role}` -- `{Get(standard, role).Hex}` in the default scheme.");
            sb.AppendLine($"    pub {Snake(role)}: Rgb,");
        }
        sb.AppendLine("}");
        sb.AppendLine();

        // --- Role accessors ----------------------------------------------------------
        sb.AppendLine("impl Palette {");
        sb.AppendLine("    /// Every role name, in the order the palette JSON declares them.");
        sb.AppendLine("    pub const ROLE_NAMES: &'static [&'static str] = &[");
        foreach (var role in roles) sb.AppendLine($"        \"{role}\",");
        sb.AppendLine("    ];");
        sb.AppendLine();
        sb.AppendLine("    /// One role by its JSON name, for code that is handed a name rather than");
        sb.AppendLine("    /// writing one -- a settings panel listing what a scheme defines, or a");
        sb.AppendLine("    /// loader reading a scheme off disk. Drawing code names the field.");
        sb.AppendLine("    pub fn role(&self, name: &str) -> Option<Rgb> {");
        sb.AppendLine("        Some(match name {");
        foreach (var role in roles) sb.AppendLine($"            \"{role}\" => self.{Snake(role)},");
        sb.AppendLine("            _ => return None,");
        sb.AppendLine("        })");
        sb.AppendLine("    }");
        sb.AppendLine();
        sb.AppendLine("    /// Overwrite one role, reporting whether the name was known.");
        sb.AppendLine("    ///");
        sb.AppendLine("    /// The half of the future filesystem loader that has to stay in step with the");
        sb.AppendLine("    /// struct: start from a shipped palette, `set_role` what the file overrides,");
        sb.AppendLine("    /// warn about the rest. Generated beside the fields so it cannot drift.");
        sb.AppendLine("    pub fn set_role(&mut self, name: &str, value: Rgb) -> bool {");
        sb.AppendLine("        match name {");
        foreach (var role in roles) sb.AppendLine($"            \"{role}\" => self.{Snake(role)} = value,");
        sb.AppendLine("            _ => return false,");
        sb.AppendLine("        }");
        sb.AppendLine("        true");
        sb.AppendLine("    }");
        sb.AppendLine("}");
        sb.AppendLine();

        // --- The schemes themselves --------------------------------------------------
        foreach (var p in palettes)
        {
            sb.AppendLine($"/// {p.Name}");
            sb.AppendLine("///");
            sb.AppendLine($"/// Source: {p.Source}");
            sb.AppendLine($"pub static {ConstName(p.Id)}: Palette = Palette {{");
            sb.AppendLine($"    id: \"{p.Id}\",");
            sb.AppendLine($"    name: \"{p.Name}\",");
            sb.AppendLine($"    gamma: \"{p.Gamma}\",");
            sb.AppendLine($"    dark: {(p.Dark ? "true" : "false")},");
            sb.AppendLine("    metrics: Metrics {");
            foreach (var key in metrics)
            {
                if (!p.Metrics.TryGetValue(key, out var value))
                    throw new InvalidDataException($"palette '{p.Id}' has no metric '{key}'");
                sb.AppendLine($"        {Snake(key)}: {value},");
            }
            sb.AppendLine("    },");
            foreach (var role in roles)
            {
                var c = Get(p, role);
                sb.AppendLine($"    {Snake(role)}: Rgb(0xff_{c.R:x2}{c.G:x2}{c.B:x2}),");
            }
            sb.AppendLine("};");
            sb.AppendLine();
        }

        // --- Lookup ------------------------------------------------------------------
        sb.AppendLine("/// Every scheme this build ships, for a settings panel to offer.");
        // One line while it fits, one per line once it does not -- which is what rustfmt
        // does, and this file is checked in and run through `cargo fmt --check` in CI. Get
        // it wrong and the tree is permanently one `cargo fmt` away from what the generator
        // produces, which quietly breaks `just check-palette`.
        var all = string.Join(", ", palettes.Select(p => "&" + ConstName(p.Id)));
        var oneLine = $"pub static ALL: &[&Palette] = &[{all}];";
        if (oneLine.Length <= 100)
        {
            sb.AppendLine(oneLine);
        }
        else
        {
            sb.AppendLine("pub static ALL: &[&Palette] = &[");
            foreach (var p in palettes) sb.AppendLine($"    &{ConstName(p.Id)},");
            sb.AppendLine("];");
        }
        sb.AppendLine();
        sb.AppendLine("/// What a component draws with when nothing selects a scheme.");
        sb.AppendLine($"pub static DEFAULT: &Palette = &{ConstName(standard.Id)};");
        sb.AppendLine();
        sb.AppendLine("/// The scheme a config file or a `--palette` flag names.");
        sb.AppendLine("///");
        sb.AppendLine("/// `None` for an unknown id rather than a fallback: only the caller knows");
        sb.AppendLine("/// whether that deserves a warning and [`DEFAULT`], or is a hard error.");
        sb.AppendLine("pub fn by_id(id: &str) -> Option<&'static Palette> {");
        sb.AppendLine("    ALL.iter().copied().find(|p| p.id == id)");
        sb.AppendLine("}");

        return Trimmed(sb);
    }

    /// <summary>lowerCamel or dotted.lowerCamel -> snake_case.</summary>
    private static string Snake(string name)
    {
        var sb = new StringBuilder();
        foreach (var ch in name)
        {
            if (ch == '.') { sb.Append('_'); continue; }
            if (char.IsUpper(ch)) { sb.Append('_').Append(char.ToLowerInvariant(ch)); continue; }
            sb.Append(ch);
        }
        return sb.ToString();
    }

    /// <summary>classic-g10 -> CLASSIC_G10.</summary>
    private static string ConstName(string id) => id.Replace('-', '_').ToUpperInvariant();

    /// <summary>
    /// The built text with its trailing blank line removed, so the generated file matches
    /// what <c>cargo fmt</c> would leave and CI's format check stays quiet.
    /// </summary>
    private static string Trimmed(StringBuilder sb) => sb.ToString().TrimEnd() + "\n";
}
